struct Noisy(&'static str);

impl Drop for Noisy {
    fn drop(&mut self) {
        println!("drop {}", self.0);
    }
}

fn main() {
    let _a = Noisy("a");
    let _b = Noisy("b");
    {
        let _c = Noisy("c");
    }
    println!("end of main");
}

fn main() {
    let v = vec![1, 2, 3];
    let it = v.iter().map(|x| {
        println!("mapping {}", x);
        x * 2
    });
    println!("created");
    let total: i32 = it.take(2).sum();
    println!("total {}", total);
}

fn main() {
    let mut v = vec![1, 2, 2, 3, 2, 1, 1];
    v.dedup();
    println!("{:?}", v);
}

fn main() {
    let a: i32 = -7;
    let b: i32 = 2;
    println!("{} {}", a / b, a % b);
    println!("{} {}", a.div_euclid(b), a.rem_euclid(b));
}

fn main() {
    let s = "caf\u{e9}";
    println!("{} {}", s.len(), s.chars().count());

    let t = "cafe\u{301}";
    println!("{} {}", t.len(), t.chars().count());

    println!("{}", s == t);
}

fn main() {
    let mut count = 0;
    for i in 0..3 {
        let count = i * 10;
        println!("{}", count);
    }
    count += 1;
    println!("final {}", count);
}

fn main() {
    let mut v = vec![("bob", 2), ("amy", 1), ("cal", 2), ("dan", 1)];
    v.sort_by_key(|&(_, k)| k);
    println!("{:?}", v);
}

fn main() {
    let mut v = vec![1, 2, 3];
    let first = &v[0];
    v.push(4);
    println!("{}", first);
}

